fn sqlite_snapshot_architect_authored_schema_limit_precedes_native_work(){use store::os_store::serialization::ArtifactSqliteSnapshotHost;use store::sqlite_snapshot::*;let expected=complete_fixture();let authored=ProgramSnapshot::SQLITE_SCHEMA.len();for case in laws()["schemaLimitOffsets"].as_array().unwrap(){let offset=case[0].as_i64().unwrap();let maximum=authored.checked_add_signed(offset as isize).unwrap();let limits=SqliteDatabaseLimits{max_schema_bytes:maximum,..SqliteDatabaseLimits::default()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=payload(&expected,encoding);let mut saw_work=false;let mut progress=|event:SqliteSnapshotProgress|{saw_work|=event.completed>0;true};let output=original_owners::with_encoding(|native_owner|expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut progress,limits), native_owner));assert_eq!(output.is_ok(),case[1].as_bool().unwrap(),"{offset} {encoding:?} output");if offset<0{assert!(!saw_work,"authored schema refused after native output work")}let mut saw_work=false;let mut progress=|event:SqliteSnapshotProgress|{saw_work|=event.completed>0;true};let actual=original_owners::with_decoding(|native_owner|ProgramSnapshot::decode_sqlite_snapshot_native(&input,&mut SqliteSnapshotControl::new(&mut progress,limits), native_owner));assert_eq!(actual.is_ok(),case[1].as_bool().unwrap(),"{offset} {encoding:?} input");if offset<0{assert!(!saw_work,"authored schema refused after native input work")}}}}
