fn sqlite_snapshot_architect_known_unicode_fields_cancel_inside_each_owned_phase(){use store::os_store::serialization::ArtifactSqliteSnapshotHost;use store::sqlite_snapshot::*;let mut expected=complete_fixture();expected.schema="😀".repeat(laws()["control"]["largeCharacters"].as_u64().unwrap()as usize);let d=database(&expected);let input=payload(&expected,SnapshotEncoding::Text);for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::EncodeNative]{let mut reached=false;let mut progress=|event:SqliteSnapshotProgress|if event.phase==phase&&event.total>=65536&&event.completed>=65536&&event.completed<event.total{reached=true;false}else{true};let mut c=SqliteSnapshotControl::new(&mut progress,SqliteDatabaseLimits::default());let result=match phase{SqliteSnapshotPhase::ProjectSnapshot=>expected.to_sqlite_database(&mut c).map(|_|()),SqliteSnapshotPhase::ReconstructSnapshot=>ProgramSnapshot::from_sqlite_database(&d,&mut c).map(|_|()),SqliteSnapshotPhase::DecodeNative=>original_owners::with_decoding(|native_owner|ProgramSnapshot::decode_sqlite_snapshot_native(&input,&mut c, native_owner)).map(|_|()),SqliteSnapshotPhase::EncodeNative=>original_owners::with_encoding(|native_owner|expected.encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut c, native_owner)).map(|_|()),_=>unreachable!()};assert!(result.is_err(),"{phase:?}");drop(c);assert!(reached,"{phase:?}");}}
