fn sqlite_snapshot_architect_owned_budget_refuses_large_fields_in_both_native_directions(){use store::os_store::serialization::ArtifactSqliteSnapshotHost;use store::sqlite_snapshot::*;let mut expected=complete_fixture();expected.schema="😀".repeat(laws()["control"]["largeCharacters"].as_u64().unwrap()as usize);let d=database(&expected);let maximum=laws()["control"]["maxOwnedBytes"].as_u64().unwrap()as usize;let limits=SqliteDatabaseLimits{max_value_bytes:maximum,..SqliteDatabaseLimits::default()};assert!(original_owners::with_sqlite_recipient(limits,&mut |_|true,|sqlite_control|ProgramSnapshot::from_sqlite_database(&d, sqlite_control)).is_err());for encoding in[SnapshotEncoding::Text,SnapshotEncoding::Binary]{let input=payload(&expected,encoding);assert!(original_owners::with_decoding(|native_owner|ProgramSnapshot::decode_sqlite_snapshot_native(&input,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner)).is_err());assert!(original_owners::with_encoding(|native_owner|expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner)).is_err());}}
