fn sqlite_snapshot_architect_complete_erased_codec_preserves_ieee_and_unsigned_words(){use store::os_store::serialization::ArtifactSqliteSnapshotHost;use store::sqlite_snapshot::*;let codec=store::bare_artifact_codec::<ProgramSnapshot,crate::standards::v1::subsets::any::schema::mutations::ProgramMutation>(crate::standards::v1::subsets::any::schema::snapshot::ARCHITECT_PROGRAM_SCHEMA);let capability=codec.snapshot_sqlite.unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.architect.program".into(),standard:"1".into(),subset:"*".into()};let corpus=laws();for raw in corpus["binary64Words"].as_array().unwrap(){let word=u64::from_str_radix(raw.as_str().unwrap(),16).unwrap();let mut expected=complete_fixture();expected.benchmarks_payload[0].value=f64::from_bits(word);expected.elements[0].area.min=Some(f64::from_bits(word));expected.relationships[0].strength=Some(f64::from_bits(word));expected.options[0].scores=vec![f64::from_bits(word),f64::from_bits(word)];expected.search_filters[0].use_count=u64::MAX;expected.templates[0].usage_count=u64::MAX;expected.knowledge_payload[0].usage_count=u64::MAX;expected.analyses[0].duration_ms=Some(u64::MAX);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=payload(&expected,encoding);let d=original_owners::with_decoding(|native_owner|(capability.export)(crate::standards::v1::subsets::any::schema::snapshot::ARCHITECT_PROGRAM_SCHEMA,&dialect,&input,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;let output=original_owners::with_encoding(|native_owner|(capability.import)(crate::standards::v1::subsets::any::schema::snapshot::ARCHITECT_PROGRAM_SCHEMA,&dialect, &mut Some(d),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;let actual=original_owners::with_decoding(|native_owner|ProgramSnapshot::decode_sqlite_snapshot_native(&output,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap();assert_eq!(actual.benchmarks_payload[0].value.to_bits(),word);assert_eq!(actual.elements[0].area.min.unwrap().to_bits(),word);assert_eq!(actual.relationships[0].strength.unwrap().to_bits(),word);assert_eq!(actual.options[0].scores.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),vec![word,word]);assert_eq!(actual.search_filters[0].use_count,u64::MAX);assert_eq!(actual.templates[0].usage_count,u64::MAX);assert_eq!(actual.knowledge_payload[0].usage_count,u64::MAX);assert_eq!(actual.analyses[0].duration_ms,Some(u64::MAX));}}}
