fn sqlite_snapshot_architect_exact_row_limits_apply_before_native_construction(){use store::os_store::serialization::ArtifactSqliteSnapshotHost;use store::sqlite_snapshot::*;let expected=complete_fixture();let d=database(&expected);let count=d.tables.iter().map(|t|t.rows.len()).sum::<usize>();let ordinary=SqliteDatabaseLimits::default();for maximum in[count,count-1]{let mut permit=|_|true;assert_eq!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits{max_rows:maximum,..ordinary},&mut permit,|sqlite_control|expected.to_sqlite_database(sqlite_control)).is_ok(),maximum==count);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut permit=|_|true;let payload=original_owners::with_encoding(|native_owner|expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut permit,ordinary), native_owner)).unwrap();let mut permit=|_|true;let mut c=SqliteSnapshotControl::new(&mut permit,SqliteDatabaseLimits{max_rows:maximum,..ordinary});assert_eq!(original_owners::with_decoding(|native_owner|ProgramSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut permit,SqliteDatabaseLimits{max_rows:maximum,..ordinary}), native_owner)).is_ok(),maximum==count);}}}
