fn sqlite_snapshot_architect_four_owned_phases_cancel_before_work(){use store::os_store::serialization::ArtifactSqliteSnapshotHost;use store::sqlite_snapshot::*;let expected=complete_fixture();let d=database(&expected);let mut permit=|_|true;let payload=original_owners::with_encoding(|native_owner|expected.encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut permit,SqliteDatabaseLimits::default()), native_owner)).unwrap();for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::EncodeNative]{let mut stop=|_|false;let mut c=SqliteSnapshotControl::new(&mut stop,SqliteDatabaseLimits::default());let actual=match phase{SqliteSnapshotPhase::ProjectSnapshot=>expected.to_sqlite_database(&mut c).map(|_|()),SqliteSnapshotPhase::ReconstructSnapshot=>ProgramSnapshot::from_sqlite_database(&d,&mut c).map(|_|()),SqliteSnapshotPhase::DecodeNative=>original_owners::with_decoding(|native_owner|ProgramSnapshot::decode_sqlite_snapshot_native(&payload,&mut c, native_owner)).map(|_|()),SqliteSnapshotPhase::EncodeNative=>original_owners::with_encoding(|native_owner|expected.encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut c, native_owner)).map(|_|()),_=>unreachable!()};assert!(actual.is_err(),"{phase:?}");}}
fn oracle(script:&str,input:&[u8])->Vec<u8>{use std::io::Write;let mut child=std::process::Command::new("bun").args(["-e",script]).stdin(std::process::Stdio::piped()).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(input).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));output.stdout}
#[test]
fn sqlite_snapshot_architect_independent_sql_edits_reject_unowned_and_inconsistent_rows(){use store::os_store::serialization::ArtifactSqliteSnapshotHost;use store::sqlite_snapshot::*;let bytes=export_sqlite_database(&database(&complete_fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let corpus=laws();let input=serde_json::json!({"bytes":bytes,"sql":corpus["malformedSql"]});let script=r#"import{Database}from'bun:sqlite';const input=JSON.parse(await Bun.stdin.text());const results=[];for(const sql of input.sql){const db=Database.deserialize(new Uint8Array(input.bytes));db.run('PRAGMA ignore_check_constraints=ON');db.run(sql);results.push(Array.from(db.serialize()));db.close()}await Bun.write(Bun.stdout,JSON.stringify(results));"#;let edits:Vec<Vec<u8>>=serde_json::from_slice(&oracle(script,input.to_string().as_bytes())).unwrap();assert_eq!(edits.len(),corpus["malformedSql"].as_array().unwrap().len());for(sql,bytes)in corpus["malformedSql"].as_array().unwrap().iter().zip(edits){let actual=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).and_then(|d|original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |_|true,|sqlite_control|ProgramSnapshot::from_sqlite_database(&d, sqlite_control)));assert!(actual.is_err(),"{sql}");}}
#[test]
fn sqlite_snapshot_architect_all_sixty_five_registers_match_real_sqlite_and_native(){use store::sqlite_snapshot::*;let expected=complete_fixture();let d=database(&expected);assert_eq!(d.tables.len(),685);assert_eq!(d.table("architect_entity_header").unwrap().rows.len(),65);assert_eq!(restored(&d),expected);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let input=serde_json::json!({"bytes":bytes,"tables":laws()["registerTables"]});let script=r#"import{Database}from'bun:sqlite';const input=JSON.parse(await Bun.stdin.text());const db=Database.deserialize(new Uint8Array(input.bytes));const rows=[];for(const[name,table]of Object.entries(input.tables)){const header=db.query('SELECT id,ordinal FROM architect_entity_header WHERE register=?').all(name);if(header.length!==1||header[0].ordinal!==0)throw Error(name);const body=db.query('SELECT id FROM '+table).all();if(body.length!==1||body[0].id!==header[0].id)throw Error(table);rows.push(name)}if(db.query('PRAGMA foreign_key_check').all().length)throw Error('foreign ownership');await Bun.write(Bun.stdout,JSON.stringify(rows));db.close();"#;let rows:Vec<String>=serde_json::from_slice(&oracle(script,input.to_string().as_bytes())).unwrap();assert_eq!(rows.len(),65);let actual=import_sqlite_database(input["bytes"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>().as_slice(),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(restored(&actual),expected);}
#[test]
fn sqlite_snapshot_architect_declared_child_projection_preserves_independent_identities(){
 let mut expected=fixture();let corpus:serde_json::Value=serde_json::from_str(fixture_text!("../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/🧩️composition/🪪️member-dialect/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let row=corpus["projectionCases"].as_array().unwrap().iter().find(|row|row["id"]=="projection-independent-local-and-target-identities").unwrap();let identity=&row["parent"][0];expected.knowledge.child_id=identity["childId"].as_str().unwrap().into();expected.knowledge.target.artifact_id=identity["artifactId"].as_str().unwrap().into();let projection=semio_framework_composition_admission::ChildRestoreProjection::from_snapshot(&expected).expect("independent local child and target identities are both literal");assert_eq!(projection.len(),2);let(_,fields)=projection.get(0).unwrap();assert_eq!(fields.child_id,"a");assert_eq!(fields.artifact_id,"b");assert!(projection.admits_member("knowledge",expected.knowledge.target.borrowed()));
}
