#[test]
fn sqlite_snapshot_architect_literal_entity_ids_admit_before_controlled_native_construction(){
 for text in laws()["idTexts"].as_array().unwrap(){let text=text.as_str().unwrap();let field=semio_framework_dsl_record::FieldValue::Text(text.into());let mut permit=|_|true;let mut control=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(1024,&mut permit);assert_eq!(<EntityId as semio_framework_dsl_record::DslField>::from_value_controlled(&field,&mut control).unwrap().0,text);}
 let field=semio_framework_dsl_record::FieldValue::Text("😀".repeat(laws()["control"]["largeCharacters"].as_u64().unwrap()as usize));let mut permit=|_|true;let mut control=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(1024,&mut permit);assert!(<EntityId as semio_framework_dsl_record::DslField>::from_value_controlled(&field,&mut control).is_err());assert!(control.owned_bytes()<=1024);let mut reached=false;let mut callback=|event:semio_framework_value_native_owned::native_decoding::NativeDecodeProgress|if event.total>=65536&&event.completed>=65536&&event.completed<event.total{reached=true;false}else{true};let mut control=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(1_000_000,&mut callback);assert!(<EntityId as semio_framework_dsl_record::DslField>::from_value_controlled(&field,&mut control).is_err());drop(control);assert!(reached);
}
#[test]
fn sqlite_snapshot_architect_literal_entity_ids_have_controlled_native_output(){
 for text in laws()["idTexts"].as_array().unwrap(){let expected=EntityId(text.as_str().unwrap().into());let mut permit=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(1024,&mut permit);assert_eq!(<EntityId as semio_framework_dsl_record::DslField>::to_value_controlled(&expected,&mut control).unwrap(),semio_framework_dsl_record::FieldValue::Text(expected.0));}
 let expected=EntityId("😀".repeat(laws()["control"]["largeCharacters"].as_u64().unwrap()as usize));let mut permit=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(1024,&mut permit);assert!(<EntityId as semio_framework_dsl_record::DslField>::to_value_controlled(&expected,&mut control).is_err());assert!(control.owned_bytes()<=1024);let mut reached=false;let mut callback=|event:semio_framework_value::native_encoding::NativeEncodeProgress|if event.total>=65536&&event.completed>=65536&&event.completed<event.total{reached=true;false}else{true};let mut control=semio_framework_value::NativeEncodeControl::new(1_000_000,&mut callback);assert!(<EntityId as semio_framework_dsl_record::DslField>::to_value_controlled(&expected,&mut control).is_err());drop(control);assert!(reached);
}
