fn semantic_cells_fixture(case:&serde_json::Value)->ProgramSnapshot{
 let mut expected=complete_fixture();
 if let Some(value)=case.get("schema"){expected.schema=value.as_str().unwrap().into();}
 if let Some(value)=case.get("subtitle"){expected.meta.subtitle=Some(value.as_str().unwrap().into());}
 if let Some(value)=case.get("word"){expected.benchmarks_payload[0].value=f64::from_bits(u64::from_str_radix(value.as_str().unwrap(),16).unwrap());}
 if let Some(value)=case.get("unsigned"){let value=value.as_str().unwrap().parse::<u64>().unwrap();expected.search_filters[0].use_count=value;expected.templates[0].usage_count=value;expected.knowledge_payload[0].usage_count=value;expected.analyses[0].duration_ms=Some(value);}
 if let Some(value)=case.get("optionalText"){expected.issues[0].root_cause=if value=="absent"{None}else{Some(crate::standards::v1::subsets::any::schema::kernel::TextField{text:String::new(),format:None})};}
 expected
}
fn semantic_cells_corpus()->serde_json::Value{serde_json::from_str(fixture_text!("../../🏅️standards/🔖️1/🪆️subsets/✳️any/🚪️io/🪶️sqlite/📸️snapshot/🧪️tests/🧫️fixtures/📏️cells/🔣️.json")).unwrap()}
#[test]
fn sqlite_snapshot_architect_complete_neutral_semantic_cells_match_independent_file_and_typed_frontier(){
 use store::{os_store::serialization::ArtifactSqliteSnapshotHost,sqlite_snapshot::*};
 let corpus=semantic_cells_corpus();assert_eq!(corpus["cases"].as_array().unwrap().len(),11);
 for case in corpus["cases"].as_array().unwrap(){
  let expected=semantic_cells_fixture(case);let d=database(&expected);let maximum=case["semanticBytes"].as_u64().unwrap()as usize;
  let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
  let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});let rows=0,bytes=0;const tables=d.query("SELECT name FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%'").all();for(const{name}of tables){const table='"'+name.replaceAll('"','""')+'"',columns=d.query("PRAGMA table_info("+table+")").all(),expression=columns.map(({name})=>{const c='"'+name.replaceAll('"','""')+'"';return"CASE typeof("+c+") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST("+c+" AS BLOB)) END";}).join("+");const cost=d.query("SELECT count(*) AS rows,coalesce(sum("+expression+"),0) AS bytes FROM "+table).get();rows+=Number(cost.rows);bytes+=Number(cost.bytes);}if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('physical owner integrity');console.log(JSON.stringify({tables:tables.length,rows,bytes}));d.close();"#;
  let physical:serde_json::Value=serde_json::from_slice(&oracle(script,&bytes)).unwrap();assert_eq!(physical,serde_json::json!({"tables":685,"rows":172,"bytes":maximum}),"{}",case["name"]);
  for limit in[maximum,maximum-1]{let limits=SqliteDatabaseLimits{max_value_bytes:limit,..SqliteDatabaseLimits::default()};assert_eq!(original_owners::with_sqlite_recipient(limits,&mut |_|true,|sqlite_control|expected.to_sqlite_database(sqlite_control)).is_ok(),limit==maximum,"{} typed projection {limit}",case["name"]);let actual=original_owners::with_sqlite_recipient(limits,&mut |_|true,|sqlite_control|ProgramSnapshot::from_sqlite_database(&d, sqlite_control));assert_eq!(actual.is_ok(),limit==maximum,"{} typed reconstruction {limit}",case["name"]);if let Ok(actual)=actual{assert_eq!(database(&actual),d);}}
 }
}
#[test]
fn sqlite_snapshot_architect_complete_neutral_semantic_cells_apply_to_both_native_directions(){
 use store::{os_store::serialization::ArtifactSqliteSnapshotHost,sqlite_snapshot::*};
 for case in semantic_cells_corpus()["cases"].as_array().unwrap(){
  let expected=semantic_cells_fixture(case);let maximum=case["semanticBytes"].as_u64().unwrap()as usize;let d=database(&expected);
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=payload(&expected,encoding);for limit in[maximum,maximum-1]{let limits=SqliteDatabaseLimits{max_value_bytes:limit,..SqliteDatabaseLimits::default()};let output=original_owners::with_encoding(|native_owner|expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner));assert_eq!(output.is_ok(),limit==maximum,"{} {encoding:?} native output {limit}",case["name"]);let actual=original_owners::with_decoding(|native_owner|ProgramSnapshot::decode_sqlite_snapshot_native(&input,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner));assert_eq!(actual.is_ok(),limit==maximum,"{} {encoding:?} native input {limit}",case["name"]);if let Ok(actual)=actual{assert_eq!(database(&actual),d);}}}
 }
}
